function formatSessionTime(value?:string){const raw=value||"21:00";const [hh,mm]=raw.split(":").map(Number);const hour=hh%12||12;return hour+(mm?":"+String(mm).padStart(2,"0"):"")+" "+(hh>=12?"pm":"am");}
