  setPlayers(current=>current.map(p=>p.id===player.id?{...p,active:false}:p));
  if(expandedPlayerId===player.id)setExpandedPlayerId("");
  void Swal.fire({toast:true,position:"top-end",icon:"success",title:"Player deleted from roster",showConfirmButton:false,timer:1700});
