 function addSession(e:FormEvent){e.preventDefault();const total=Number(amount), actualTurfCharges=Number(turfCharges), per=Number(contribution);if(total<=0||actualTurfCharges<=0||actualTurfCharges>total||(mode==="fund"&&(per<=0||per>total))){if(mode==="fund"&&per>total)void Swal.fire({icon:"warning",title:"Contribution exceeds session cost",text:"Fixed contribution per person cannot be higher than the total session expenses."});return;}const values={date,venue,startTime:sessionStartTime,endTime:sessionEndTime,total,turfCharges:actualTurfCharges,mode,contribution:mode==="fund"?per:0};if(editingSessionId){setSessions(current=>current.map(s=>{if(s.id!==editingSessionId)return s;const financeChanged=s.total!==total||s.turfCharges!==actualTurfCharges||s.mode!==mode||s.contribution!==(mode==="fund"?per:0);return {...s,...values,organiserAdvanceSettled:financeChanged?false:s.organiserAdvanceSettled,organiserAdvanceSettledAt:financeChanged?undefined:s.organiserAdvanceSettledAt};}));void Swal.fire({icon:"success",title:"Changes saved",text:"Your session has been updated.",timer:1500,showConfirmButton:false});}else{const session:Session={id:crypto.randomUUID(),...values,participants:[],attendance:{}};setSessions(current=>[session,...current]);setDetailSessionId(session.id);setTab("Session details");void Swal.fire({toast:true,position:"top-end",icon:"success",title:"Session created",text:"Add the players attending, then share the session details whenever you are ready.",showConfirmButton:false,timer:3200,timerProgressBar:true});}setAmount("");setTurfCharges("");setShowSession(false);setEditingSessionId("");setSessionStartTime("21:00");setSessionEndTime("00:00");}
