 function addPlayerFromAttendance(){const playerName=quickPlayerName.trim();const digits=quickPlayerPhone.trim();if(!playerName)return;if(!/^[6-9][0-9]{9}$/.test(digits)){setQuickPhoneError("Enter a valid 10-digit mobile number. This field is mandatory.");return;}setQuickPhoneError("");const duplicate=players.some(p=>p.name.trim().toLowerCase()===playerName.toLowerCase());if(duplicate){setQuickPhoneError("This player name is already in use. Please use a unique name or add a nickname.");void Swal.fire({icon:"warning",title:"Player name already exists",text:"Please use a unique name or add a nickname to avoid confusion when recording payments."});return;}setQuickPhoneError("");const player:Player={id:crypto.randomUUID(),name:playerName,phone:digits};setPlayers(current=>[...current,player]);setAttendanceDraft(current=>[...current,player.id]);setQuickPlayerName("");setQuickPlayerPhone("");setShowQuickPlayerForm(false);Swal.fire({toast:true,position:"top-end",icon:"success",title:"Player added to roster",showConfirmButton:false,timer:1600});}
 function saveAttendance(e:FormEvent){e.preventDefault();const id=attendanceSessionId;const names=attendanceDraft.map(pid=>players.find(p=>p.id===pid)?.name.trim().toLowerCase()).filter((name):name is string=>!!name);if(new Set(names).size!==names.length){void Swal.fire({icon:"warning",title:"Duplicate player names in this session",text:"Please keep every player name unique. Edit one of the names or add a nickname before saving attendance, so payments are recorded against the correct person."});return;}setSessions(current=>current.map(s=>s.id===id?{...s,participants:attendanceDraft,attendance:Object.fromEntries(attendanceDraft.map(pid=>[pid,1]))}:s));closeAttendance();resetShareProgress();setAnnouncementSessionId(attendanceDraft.length>0?id:"");}
 function approveSessionPayment(s:Session,player:Player){const due=amountDueForSession(player.id,s.id);if(due<=0){void Swal.fire({icon:"info",title:"Payment already complete"});return;}void Swal.fire({title:"Approve payment?",html:"Record <b>"+money(due)+"</b> received from "+player.name+" for "+s.venue+"?",icon:"question",showCancelButton:true,confirmButtonText:"Yes, record payment"}).then(result=>{if(result.isConfirmed){setPayments(current=>[{id:crypto.randomUUID(),playerId:player.id,amount:due,date:new Date().toISOString().slice(0,10),note:"Approved by organiser",method:"UPI",sessionId:s.id},...current]);setSessions(current=>current.map(x=>x.id===s.id?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));void Swal.fire({icon:"success",title:"Payment recorded",timer:1400,showConfirmButton:false});}});}
