 function addPayment(e:FormEvent){e.preventDefault();const n=Number(payAmount);if(hasDuplicatePaymentNames&&!editingPaymentId){void Swal.fire({icon:"warning",title:"Duplicate player names in this session",text:"Please rename one player or add a nickname before recording payment."});return;}if(!payPlayer||!paySession||n<=0)return;const record:Payment={id:editingPaymentId||crypto.randomUUID(),playerId:payPlayer,amount:n,date:new Date().toISOString().slice(0,10),note:payNote,method:payMethod,sessionId:paySession};setPayments(current=>editingPaymentId?current.map(p=>p.id===editingPaymentId?{...p,...record,date:p.date}:p):[record,...current]);setSessions(current=>current.map(x=>x.id===paySession?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));setPayAmount("");setPayNote("");setEditingPaymentId("");void Swal.fire({toast:true,position:"top-end",icon:"success",title:editingPaymentId?"Payment updated":"Payment recorded",showConfirmButton:false,timer:1500});}
 function editPayment(p:Payment){setEditingPaymentId(p.id);setPaySession(p.sessionId);setPayPlayer(p.playerId);const player=players.find(x=>x.id===p.playerId);setPayPlayerName(player?.name||"");setPayPlayerPhone(p.playerId);setPayAmount(String(p.amount));setPayNote(p.note);setPayMethod(p.method);setTab("Payments");}
 async function deletePayment(p:Payment){const result=await Swal.fire({title:"Delete payment record?",text:"This will reverse the recorded payment and increase the player's outstanding balance.",icon:"warning",showCancelButton:true,confirmButtonText:"Delete payment",cancelButtonText:"Cancel",confirmButtonColor:"#dc2626"});if(!result.isConfirmed)return;setPayments(current=>current.filter(x=>x.id!==p.id));setSessions(current=>current.map(x=>x.id===p.sessionId?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));if(editingPaymentId===p.id){setEditingPaymentId("");setPayPlayer("");setPayAmount("");setPayNote("");}void Swal.fire({icon:"success",title:"Payment deleted",timer:1300,showConfirmButton:false});}
 function expectedForPlayer(s:Session,playerId:string){if(!s.participants.includes(playerId))return 0;if(s.mode==="fund")return s.contribution;const count=s.participants.length;return count?s.total/count:0;}
 function sessionReceived(s:Session){return payments.filter(p=>p.sessionId===s.id).reduce((sum,p)=>sum+p.amount,0);}
 function sessionOrganiserAdvance(s:Session){if(s.mode!=="fund"||!s.participants.length)return 0;return s.organiserAdvanceSettled?(s.organiserAdvanceSettledAmount??Math.max(0,s.total-sessionReceived(s))):Math.max(0,s.total-sessionReceived(s));}
 function fundBalanceAfterSession(s:Session){const relevant=sessions.filter(x=>x.mode==="fund"&&x.date<=s.date),ids=new Set(relevant.map(x=>x.id));const credits=payments.filter(p=>ids.has(p.sessionId)).reduce((n,p)=>n+p.amount,0),expenses=relevant.reduce((n,x)=>n+x.total,0),manual=fundTransactions.filter(t=>t.date<=s.date).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0),advances=relevant.filter(x=>!x.organiserAdvanceSettled).reduce((n,x)=>n+sessionOrganiserAdvance(x),0);return openingFund+credits-expenses+manual+advances;}
 function fundBalanceBeforeSession(s:Session){const prior=sessions.filter(x=>x.mode==="fund"&&x.date<s.date),ids=new Set(prior.map(x=>x.id));const credits=payments.filter(p=>ids.has(p.sessionId)&&p.date<s.date).reduce((n,p)=>n+p.amount,0),expenses=prior.reduce((n,x)=>n+x.total,0),manual=fundTransactions.filter(t=>t.date<s.date).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0),advances=prior.reduce((sum,x)=>{const settledBefore=x.organiserAdvanceSettledAt?x.organiserAdvanceSettledAt<s.date:false;if(settledBefore)return sum;const received=payments.filter(p=>p.sessionId===x.id&&p.date<s.date).reduce((n,p)=>n+p.amount,0);return sum+Math.max(0,x.total-received);},0);return openingFund+credits-expenses+manual+advances;}
 function sessionFundSurplus(s:Session){return s.mode==="fund"?Math.max(0,sessionReceived(s)-s.total):0;}
 function latestSessionForPlayer(playerId:string){return [...sessions].filter(s=>s.participants.includes(playerId)).sort((a,b)=>b.date.localeCompare(a.date))[0];}
 function amountDueForSession(playerId:string,sessionId:string){const s=sessions.find(x=>x.id===sessionId);if(!s)return 0;const expected=expectedForPlayer(s,playerId);const paid=payments.filter(p=>p.playerId===playerId&&p.sessionId===sessionId).reduce((n,p)=>n+p.amount,0);return Math.max(0,expected-paid);}
 function sessionOutstanding(s:Session){return s.participants.reduce((n,id)=>n+amountDueForSession(id,s.id),0);}
 function sessionPaid(s:Session,playerId:string){return payments.filter(p=>p.sessionId===s.id&&p.playerId===playerId).reduce((total,p)=>total+p.amount,0);}
 useEffect(()=>{if(!sessions.length)return;if(!paySession){const latest=[...sessions].sort((a,b)=>b.date.localeCompare(a.date))[0];setPaySession(latest.id);}},[sessions,paySession]);
 
 useEffect(()=>{if(!payPlayer||!paySession||editingPaymentId)return;const due=amountDueForSession(payPlayer,paySession);setPayAmount(due>0?String(Math.round(due*100)/100):"");},[payPlayer,paySession,sessions,payments,editingPaymentId]);
 function savePayeeDetails(e:FormEvent){e.preventDefault();const cleanName=payeeDraft.trim(),cleanUpi=upiDraft.trim(),cleanPhone=paymentPhoneDraft.replace(/\D/g,"");if(!cleanName||!cleanUpi){void Swal.fire({icon:"warning",title:"Complete payment details",text:"Enter both the payee name and UPI ID."});return;}if(cleanPhone&&!/^[6-9][0-9]{9}$/.test(cleanPhone)){void Swal.fire({icon:"warning",title:"Check payment contact number",text:"Enter a valid 10-digit Indian mobile number, or leave it blank."});return;}setPayeeName(cleanName);setUpiId(cleanUpi);setPaymentPhone(cleanPhone);void Swal.fire({icon:"success",title:"Payment details updated",text:"New UPI links will use these details.",timer:1500,showConfirmButton:false});}
 function saveFundManagerDetails(e:FormEvent){e.preventDefault();const cleanName=fundManagerNameDraft.trim(),digits=fundManagerPhoneDraft.replace(/\D/g,"");if(!cleanName||!/^[6-9][0-9]{9}$/.test(digits)){void Swal.fire({icon:"warning",title:"Check fund manager details",text:"Enter a name and a valid 10-digit Indian mobile number."});return;}setFundManagerName(cleanName);setFundManagerPhone(digits);localStorage.setItem("tm-fund-manager-name",cleanName);localStorage.setItem("tm-fund-manager-phone",digits);void Swal.fire({icon:"success",title:"Fund manager details updated",timer:1400,showConfirmButton:false});}
  function remindFundManagerForSession(s:Session){const amount=sessionOrganiserAdvance(s);if(amount<=0||s.organiserAdvanceSettled)return;const payload={n:"Cricket fund settlement",a:amount.toFixed(2),u:upiId,p:payeeName,m:paymentPhone,t:"TurfMate fund settlement - "+s.venue+" - "+s.date};const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary="";bytes.forEach(byte=>binary+=String.fromCharCode(byte));const token=btoa(binary).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");const qrLink=paymentLinkBaseUrl()+"/p/"+token;const message="Hi "+fundManagerName+" 👋\n\nPlease settle the organiser advance for this TurfMate cricket session. 🏏\n\n*Session:* "+s.venue+"\n*Date:* "+s.date+"\n*Amount to transfer:* "+money(amount)+"\n\n"+paymentLinkInstructions(qrLink,"Open your organiser settlement payment link")+"\n\nI’ll mark this session’s organiser advance as settled in TurfMate once the transfer is received. Thank you!";openWhatsappMessage(message,fundManagerPhone);}
 function settleOrganiserAdvance(s:Session){if(s.organiserAdvanceSettled)return;const outstanding=sessionOutstanding(s);if(outstanding>0){void Swal.fire({icon:"warning",title:"Player contributions are still pending",text:"Collect all player contributions before settling the organiser advance. Remaining amount: "+money(outstanding)+"."});return;}const advance=sessionOrganiserAdvance(s);if(!advance)return;if(fundBalance-advance<0){void Swal.fire({icon:"warning",title:"Insufficient cricket fund",text:"The available fund balance is not enough to settle this organiser advance yet."});return;}void Swal.fire({title:"Mark organiser advance as settled?",text:"All player contributions are received. Record "+money(advance)+" as reimbursed to the organiser from the cricket fund.",icon:"question",showCancelButton:true,confirmButtonText:"Yes, mark settled"}).then(result=>{if(result.isConfirmed){setSessions(current=>current.map(x=>x.id===s.id?{...x,organiserAdvanceSettled:true,organiserAdvanceSettledAt:new Date().toISOString().slice(0,10),organiserAdvanceSettledAmount:advance}:x));void Swal.fire({icon:"success",title:"Advance settled",timer:1400,showConfirmButton:false});}});}
 function addFundEntry(e:FormEvent){e.preventDefault();const n=Number(fundAmount);if(n<=0)return;if(fundType==="Withdrawal"&&n>fundBalance){void Swal.fire({icon:"warning",title:"Insufficient cricket fund",text:"The withdrawal cannot be greater than the current fund balance of "+money(fundBalance)+"."});return;}setFundTransactions(current=>[{id:crypto.randomUUID(),date:new Date().toISOString().slice(0,10),type:fundType,amount:n,note:fundNote.trim()},...current]);setFundAmount("");setFundNote("");void Swal.fire({icon:"success",title:fundType==="Contribution"?"Contribution added":"Withdrawal recorded",timer:1400,showConfirmButton:false});}
 function isLedgerSessionSettled(s:Session){return s.date>="2026-11-01"&&s.participants.length>0&&sessionOutstanding(s)<=0&&(sessionOrganiserAdvance(s)<=0||s.organiserAdvanceSettled);}
 function applyReportPreset(value:string){setReportPreset(value);const now=new Date(),fmt=(d:Date)=>d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");let from=new Date(now.getFullYear(),now.getMonth(),1);if(value==="previous-month")from=new Date(now.getFullYear(),now.getMonth()-1,1);else if(value==="last-3")from=new Date(now.getFullYear(),now.getMonth()-2,1);else if(value==="last-6")from=new Date(now.getFullYear(),now.getMonth()-5,1);else if(value==="year-to-date")from=new Date(now.getFullYear(),0,1);else if(value==="last-year") {from=new Date(now.getFullYear()-1,0,1);setReportEnd(fmt(new Date(now.getFullYear()-1,11,31)));}else if(value==="last-12")from=new Date(now.getFullYear(),now.getMonth()-11,1);if(value==="previous-month")setReportEnd(fmt(new Date(now.getFullYear(),now.getMonth(),0)));else if(value!=="custom"&&value!=="last-year")setReportEnd(fmt(now));if(value!=="custom")setReportStart(fmt(from));}
 function downloadReport(){
  if(!reportStart||!reportEnd||reportStart>reportEnd){void Swal.fire({icon:"warning",title:"Check report dates",text:"Please choose a valid date range."});return;}
  const inRange=(value:string)=>value>=reportStart&&value<=reportEnd;
  const rangeSessions=sessions.filter(s=>inRange(s.date)).sort((a,b)=>a.date.localeCompare(b.date));
  const rangePayments=payments.filter(p=>inRange(p.date)).sort((a,b)=>a.date.localeCompare(b.date));
  const rangeFund=fundTransactions.filter(t=>inRange(t.date)).sort((a,b)=>a.date.localeCompare(b.date));
  const isFundPayment=(p:Payment)=>sessions.some(s=>s.id===p.sessionId&&s.mode==="fund");
  const fundReport=hasCricketFund||sessions.some(s=>s.mode==="fund");
  const balanceAt=(date:string,exclusive=false)=>{
   const before=(value:string)=>exclusive?value<date:value<=date;
   const credits=payments.filter(p=>before(p.date)&&isFundPayment(p)).reduce((n,p)=>n+p.amount,0);
   const expenses=sessions.filter(s=>before(s.date)&&s.mode==="fund").reduce((n,s)=>n+s.total,0);
   const manual=fundTransactions.filter(t=>before(t.date)).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0);
   const advances=sessions.filter(s=>before(s.date)&&s.mode==="fund").reduce((sum,s)=>{const settledByCutoff=s.organiserAdvanceSettledAt?(exclusive?s.organiserAdvanceSettledAt<date:s.organiserAdvanceSettledAt<=date):false;if(settledByCutoff)return sum;const receivedByCutoff=payments.filter(p=>p.sessionId===s.id&&before(p.date)).reduce((n,p)=>n+p.amount,0);return sum+Math.max(0,s.total-receivedByCutoff);},0);
   return openingFund+credits-expenses+manual+advances;
  };
  const opening=balanceAt(reportStart,true),closing=balanceAt(reportEnd);
  const spendInRange=rangeSessions.reduce((n,s)=>n+s.total,0);
  const playerContributions=rangePayments.filter(isFundPayment).reduce((n,p)=>n+p.amount,0);
  const manualIn=rangeFund.filter(t=>t.type==="Contribution").reduce((n,t)=>n+t.amount,0);
  const manualOut=rangeFund.filter(t=>t.type==="Withdrawal").reduce((n,t)=>n+t.amount,0);
  const doc=new jsPDF({orientation:"portrait",unit:"mm",format:"a4"});doc.setCharSpace(0);
  const W=210,L=14,R=196,navy=[19,42,61] as [number,number,number],green=[24,151,105] as [number,number,number],pale=[239,247,243] as [number,number,number],ink=[43,57,72] as [number,number,number],muted=[112,127,143] as [number,number,number];let y=0;
  const setText=(rgb:[number,number,number])=>doc.setTextColor(rgb[0],rgb[1],rgb[2]);
  const header=()=>{doc.setFillColor(...navy);doc.rect(0,0,W,34,"F");doc.setFillColor(...green);doc.rect(0,33,W,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(19);setText([255,255,255]);doc.text("TurfMate",L,15);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text("MANHATTAN CRICKET  /  FINANCE REPORT",L,23);};
  const footer=()=>{const count=doc.getNumberOfPages();for(let p=1;p<=count;p++){doc.setPage(p);doc.setDrawColor(224,231,237);doc.line(L,284,R,284);doc.setFont("helvetica","normal");doc.setFontSize(8);setText(muted);doc.text("Generated by TurfMate  •  "+new Date().toLocaleDateString("en-IN"),L,290);doc.text("Page "+p+" of "+count,R,290,{align:"right"});}};
  header();y=45;doc.setFont("helvetica","bold");doc.setFontSize(16);setText(navy);doc.text(fundReport?"Cricket Finance & Fund Report":"Cricket Finance Report",L,y);y+=7;doc.setFont("helvetica","normal");doc.setFontSize(9);setText(muted);doc.text("Reporting period: "+reportStart+"  to  "+reportEnd,L,y);y+=12;
  const cards: [string,string][] = fundReport?[["OPENING BALANCE",money(opening)],["PLAYER CONTRIBUTIONS",money(playerContributions)],["TURF EXPENSES",money(rangeSessions.reduce((n,s)=>n+(s.mode==="fund"?s.total:0),0))],["CLOSING BALANCE",money(closing)]]:[["SESSIONS",String(rangeSessions.length)],["PLAYER PAYMENTS",money(rangePayments.reduce((n,p)=>n+p.amount,0))],["TURF EXPENSES",money(spendInRange)]];
  const gap=4,cw=(W-2*L-gap*(cards.length-1))/cards.length;cards.forEach((card,i)=>{const x=L+i*(cw+gap);doc.setFillColor(246,248,250);doc.roundedRect(x,y,cw,22,2,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(6.5);setText(muted);doc.text(card[0],x+3,y+7);doc.setFontSize(10);setText(i===cards.length-1?green:navy);doc.text(card[1],x+3,y+16);});y+=32;
  const drawSection=(title:string,headers:string[],rows:string[][],widths:number[])=>{
   const previewRowCount=Math.min(rows.length,3);const minimumSectionHeight=12+8+(rows.length?previewRowCount*8:10)+4;if(y+minimumSectionHeight>278){doc.addPage();header();y=45;}doc.setFillColor(...pale);doc.roundedRect(L,y,W-2*L,9,1.5,1.5,"F");doc.setFont("helvetica","bold");doc.setFontSize(10);setText(navy);doc.text(title,L+3,y+6);y+=12;
   const totalW=widths.reduce((a,b)=>a+b,0),drawHead=()=>{doc.setFillColor(...navy);doc.rect(L,y,totalW,8,"F");doc.setFont("helvetica","bold");doc.setFontSize(7);setText([255,255,255]);let x=L;headers.forEach((h,i)=>{doc.text(h,x+2,y+5.3);x+=widths[i];});y+=8;};drawHead();
   if(!rows.length){doc.setFont("helvetica","italic");doc.setFontSize(8);setText(muted);doc.text("No records for this period.",L+2,y+6);y+=10;return;}
   rows.forEach((row,index)=>{if(y+8>278){doc.addPage();header();y=45;drawHead();}if(index%2===0){doc.setFillColor(248,250,252);doc.rect(L,y,totalW,8,"F");}doc.setFont("helvetica","normal");doc.setFontSize(7);setText(ink);let x=L;row.forEach((cell,i)=>{doc.text(doc.splitTextToSize(String(cell),widths[i]-4).slice(0,1),x+2,y+5.3);x+=widths[i];});doc.setDrawColor(231,236,241);doc.line(L,y+8,L+totalW,y+8);y+=8;});y+=8;
  };
  drawSection("Session & turf expense register",["DATE","VENUE","CONTRIBUTION MODEL","TURF COST"],rangeSessions.map(s=>[s.date,s.venue,s.mode==="fund"?"Fixed ₹"+s.contribution+"/player":"Equal split",money(s.total)]),[29,65,57,31]);
  drawSection("Player payment register",["DATE","PLAYER","SESSION","METHOD","AMOUNT"],rangePayments.map(p=>[p.date,players.find(x=>x.id===p.playerId)?.name||"Player",sessions.find(s=>s.id===p.sessionId)?.venue||"Session",p.method,money(p.amount)]),[27,39,55,28,33]);
  if(fundReport){
   drawSection("Organiser advances & fund surplus",["DATE","SESSION","ORGANISER ADVANCE","SETTLEMENT / SURPLUS"],rangeSessions.filter(s=>s.mode==="fund"&&(sessionOrganiserAdvance(s)>0||sessionFundSurplus(s)>0)).map(s=>[s.date,s.venue,sessionOrganiserAdvance(s)>0?money(sessionOrganiserAdvance(s)):"-",sessionOrganiserAdvance(s)>0?(s.organiserAdvanceSettled?"Settled · fund deduction":"Pending"):("Fund surplus "+money(sessionFundSurplus(s)))]),[25,48,52,57]);
   drawSection("Central cricket fund movements",["DATE","ENTRY","DESCRIPTION","CREDIT","DEBIT"],[
    ...rangePayments.filter(isFundPayment).map(p=>[p.date,"Player payment",players.find(x=>x.id===p.playerId)?.name||"Player",money(p.amount),"-"]),
    ...rangeSessions.filter(s=>s.mode==="fund").map(s=>[s.date,"Turf expense",s.venue,"-",money(s.total)]),
    ...rangeSessions.filter(s=>s.mode==="fund"&&sessionOrganiserAdvance(s)>0).map(s=>[s.date,"Organiser advance",s.venue,money(s.organiserAdvanceSettled?(s.organiserAdvanceSettledAmount||sessionOrganiserAdvance(s)):sessionOrganiserAdvance(s)),"-"]),
    ...rangeSessions.filter(s=>s.mode==="fund"&&s.organiserAdvanceSettled).map(s=>[s.organiserAdvanceSettledAt||s.date,"Advance settled",s.venue,"-",money(s.organiserAdvanceSettledAmount||sessionOrganiserAdvance(s))]),
    ...rangeFund.map(t=>[t.date,t.type,t.note||"-",t.type==="Contribution"?money(t.amount):"-",t.type==="Withdrawal"?money(t.amount):"-"])
   ].sort((a,b)=>a[0].localeCompare(b[0])),[25,35,57,34,31]);
   if(y>244){doc.addPage();header();y=45;}doc.setFillColor(...navy);doc.roundedRect(L,y,W-2*L,38,2,2,"F");doc.setCharSpace(0);doc.setFont("helvetica","bold");doc.setFontSize(9);setText([255,255,255]);doc.text("FUND RECONCILIATION",L+4,y+7);doc.setCharSpace(0);doc.setFont("helvetica","normal");doc.setFontSize(7.5);const reconciliationLine1="Opening balance: "+money(opening)+"    Credits: "+money(playerContributions+manualIn);const reconciliationLine2="Turf expenses / withdrawals: "+money(manualOut+rangeSessions.filter(s=>s.mode==="fund").reduce((n,s)=>n+s.total,0))+"    Pending organiser advances: "+money(rangeSessions.filter(s=>s.mode==="fund"&&!s.organiserAdvanceSettled).reduce((n,s)=>n+sessionOrganiserAdvance(s),0));setText([255,255,255]);doc.setCharSpace(0);doc.text(reconciliationLine1,L+4,y+15,{charSpace:0});doc.setCharSpace(0);doc.text(doc.splitTextToSize(reconciliationLine2,W-2*L-8),L+4,y+21,{charSpace:0});doc.setCharSpace(0);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Closing balance: "+money(closing),L+4,y+32,{charSpace:0});y+=43;
  }
  footer();doc.save("TurfMate-Finance-Report-"+reportStart+"-to-"+reportEnd+".pdf");
 }

