  const totalPlayers=rows.reduce((sum,row)=>sum+row.players,0);
  const firstOpening=rows.length?rows[0].opening:openingBalance;
  const doc=new jsPDF({orientation:"landscape",unit:"mm",format:"a4"});doc.setCharSpace(0);
  const W=297,H=210,L=12,tableW=273,navy=[19,42,61] as [number,number,number],green=[24,151,105] as [number,number,number],pale=[239,247,243] as [number,number,number],ink=[43,57,72] as [number,number,number],muted=[112,127,143] as [number,number,number],white=[255,255,255] as [number,number,number],line=[222,230,236] as [number,number,number];
  const setText=(rgb:[number,number,number])=>doc.setTextColor(rgb[0],rgb[1],rgb[2]);
  const fmtMoney=(value:number)=>"Rs. "+Math.round(value).toLocaleString("en-IN");
