 function paymentLinkInstructions(link:string,heading="Open your payment page"){return "💳 *"+heading+"*\n"+link+"\n\n1. Download the personalised QR from the page.\n2. If you are using an iPhone and it does not save to Photos, take a screenshot of the QR displayed on the page.\n3. Open your UPI app and choose Scan QR → Gallery/Photos (if supported).\n4. Select the QR image and verify the payee and amount before paying.\n\nAlternatively, copy the UPI ID from the page and use your UPI app’s Pay to UPI ID option.";}
 const paymentLinkBaseUrl=()=>{const env=(import.meta as any).env||{};const host=env.VITE_VERCEL_TARGET_ENV==="production"?env.VITE_VERCEL_PROJECT_PRODUCTION_URL:env.VITE_VERCEL_BRANCH_URL;return host?"https://"+host:window.location.origin;};
