  async function buildGroupQrCard(qrBlob:Blob,s:Session):Promise<Blob>{const imageUrl=URL.createObjectURL(qrBlob);try{const qrImage=new Image();await new Promise<void>((resolve,reject)=>{qrImage.onload=()=>resolve();qrImage.onerror=()=>reject(new Error("Unable to load group payment QR"));qrImage.src=imageUrl;});const canvas=document.createElement("canvas");canvas.width=1000;canvas.height=1120;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Canvas is unavailable");ctx.fillStyle="#F1F6F4";ctx.fillRect(0,0,1000,1120);ctx.fillStyle="#FFFFFF";ctx.fillRect(34,34,932,1052);ctx.fillStyle="#147A59";ctx.font="800 38px Arial";ctx.fillText("TURFMATE",78,112);ctx.fillStyle="#728278";ctx.font="700 20px Arial";ctx.textAlign="right";ctx.fillText("GROUP PAYMENT QR",922,110);ctx.textAlign="left";ctx.fillStyle="#203A32";ctx.font="800 46px Arial";ctx.fillText(s.venue,78,205,840);ctx.fillStyle="#728278";ctx.font="600 25px Arial";ctx.fillText(s.date+" · "+formatSessionTime(s.startTime)+" to "+formatSessionTime(s.endTime),78,258);ctx.fillStyle="#147A59";ctx.font="800 54px Arial";ctx.fillText(money(groupPaymentAmount(s))+" per player",78,355);ctx.fillStyle="#728278";ctx.font="600 22px Arial";ctx.fillText("Scan to pay · Amount and session note prefilled",78,410);ctx.fillStyle="#FFFFFF";ctx.fillRect(250,450,500,500);ctx.drawImage(qrImage,270,470,460,460);ctx.fillStyle="#203A32";ctx.font="700 24px Arial";ctx.textAlign="center";ctx.fillText("Pay "+payeeName,500,1010);ctx.fillStyle="#728278";ctx.font="500 19px Arial";ctx.fillText("TurfMate · "+groupPaymentNote(s),500,1048);return await new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("Unable to render group QR card")),"image/png"));}finally{URL.revokeObjectURL(imageUrl);}}
