  const header=()=>{doc.setFillColor(...navy);doc.rect(0,0,W,36,"F");doc.setFillColor(...green);doc.rect(0,35,W,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(21);doc.setTextColor(255,255,255);doc.text("TurfMate",L,16);doc.setFontSize(9);doc.setFont("helvetica","normal");doc.text("MANHATTAN CRICKET  /  SESSION FINANCE",L,25);doc.setFont("helvetica","bold");doc.text("SESSION REPORT",R,16,{align:"right"});};
