  header();y=48;doc.setFont("helvetica","bold");doc.setFontSize(17);doc.setTextColor(...navy);doc.text(s.venue,L,y);y+=7;doc.setFont("helvetica","normal");doc.setFontSize(9);doc.setTextColor(...muted);doc.text(dateLabel+"   ·   "+formatSessionTime(s.startTime)+" to "+formatSessionTime(s.endTime),L,y);y+=10;
