   doc.setFont("helvetica","bold");doc.setFontSize(7);doc.setTextColor(...muted);doc.text("OPENING BALANCE · BEFORE SESSION",L+4,fundCardY+7);doc.text("CLOSING BALANCE · AFTER SESSION",L+98,fundCardY+7);
   doc.setFontSize(11);doc.setTextColor(...navy);doc.text("Rs. "+Math.round(openingBalance).toLocaleString("en-IN"),L+4,fundCardY+16);doc.setTextColor(...green);doc.text("Rs. "+Math.round(closingBalance).toLocaleString("en-IN"),L+98,fundCardY+16);y+=28;
   const advance=sessionOrganiserAdvance(s),surplus=sessionFundSurplus(s);
   if(advance>0){section("ORGANISER ADVANCE STATUS");const settled=!!s.organiserAdvanceSettled,bg=settled?[232,247,240] as [number,number,number]:[255,244,230] as [number,number,number],fg=settled?[22,126,84] as [number,number,number]:[181,91,24] as [number,number,number];doc.setFillColor(...bg);doc.roundedRect(L,y,182,20,2,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(9);doc.setTextColor(...fg);doc.text(settled?"SETTLED":"PENDING",L+4,y+8);doc.setFontSize(8);doc.setFont("helvetica","normal");doc.text(settled?"Organiser reimbursed from the cricket fund":"Organiser reimbursement is still pending",L+4,y+15);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Rs. "+Math.round(s.organiserAdvanceSettled?(s.organiserAdvanceSettledAmount||advance):advance).toLocaleString("en-IN"),R-4,y+12,{align:"right"});y+=25;}
   if(surplus>0)infoRow("Surplus added to cricket fund","Rs. "+Math.round(surplus).toLocaleString("en-IN"));if(advance===0&&surplus===0)infoRow("Organiser advance / surplus","No adjustment for this session");
