  y+=7;section("PAYMENT RECORD HISTORY");const rows=payments.filter(p=>p.sessionId===s.id).sort((a,b)=>a.date.localeCompare(b.date)),px=[L+3,72,113,139,166];tableHeader(["PLAYER","DATE","METHOD","AMOUNT","REFERENCE / NOTE"],px);
  if(!rows.length){doc.setFont("helvetica","italic");doc.setFontSize(8);doc.setTextColor(...muted);doc.text("No payment records have been added for this session.",L+3,y+6);y+=10;}else rows.forEach((p,i)=>{if(y>270){doc.addPage();header();y=48;tableHeader(["PLAYER","DATE","METHOD","AMOUNT","REFERENCE / NOTE"],px);}if(i%2===0){doc.setFillColor(246,249,250);doc.rect(L,y,182,9,"F");}const player=players.find(x=>x.id===p.playerId);doc.setFont("helvetica","normal");doc.setFontSize(7.5);doc.setTextColor(...ink);doc.text(player?.name||"Player",px[0],y+6);doc.text(p.date,px[1],y+6);doc.text(p.method,px[2],y+6);doc.setFont("helvetica","bold");doc.text("Rs. "+Math.round(p.amount),px[3],y+6);doc.setFont("helvetica","normal");doc.setFontSize(6.5);doc.text(paymentNoteLabel(p.note),px[4],y+6);y+=9;});
